///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_viewerUrl
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_viewerUrl = async function () {
    const sbmOptions = {
        id: "tx_fn_viewerUrl",
        method: "post",
        action: "/EsgSearch.do",
        ref: "dma_viewerUrlReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf10002.tx_fn_viewerUrl" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.DocPrint
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.DocPrint = function () {
    /* sdd-asis-lifecycle:begin DocPrint — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const docUrl = sessionStorage.getItem("gDocUrl");
    const printType = sessionStorage.getItem("gSndlocTpCd");
    const vFromUpclssCd = sessionStorage.getItem("gFromUpclssCd");
    const printAcptNo = sessionStorage.getItem("gPrintAcptNo");
    const printDocNo = sessionStorage.getItem("gPrintDocNo");
    if (printType === '20' && vFromUpclssCd !== '01') {
        const usrl = "/disclsdocviewer/pdfView.jsp?type=pdf" + "&acptNo=" + printAcptNo + "&docNo=" + printDocNo + "&SCREN_ID=" + "/jldstf10002/jldstf10002.xml" + "&SCREN_PROCES_TP_CD=05" + "&docpath=" + docUrl;
        const winTitle = "공시뷰어";
        window.open(usrl, "testPop", "left=0,top=0,width=850,height=750,resizable=yes,scrollbars=no,location=no,status=no");
    } else {
        scwin.ifrCtrl.focus();
        $c.win.popupPrint();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.showPrintForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.showPrintForm = function () {
    /* sdd-asis-lifecycle:begin showPrintForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const url = location.href;
    if (url.indexOf("?") != -1) {
        const queryString = url.substring(url.indexOf("?") + 1);
        const paramList = queryString.split("&");
        for (i = 0; i < paramList.length; i++) {
            let tmp = paramList[i];
            tmp = tmp.split("=");
            if (tmp[0] === "gPrintUrl") {
                sessionStorage.setItem(tmp[0], decodeURIComponent(tmp[1]));
            } else {
                sessionStorage.setItem(tmp[0], tmp[1]);
            }
        }
    }
    scwin.showLangBtn();
    const gPrintUrl = sessionStorage.getItem("gPrintUrl");
    scwin.gUrl = gPrintUrl;
    $c.util.getComponent("ifrCtrl").src = scwin.gUrl;
    scwin.viewerBtnStyleCheck();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.openNewWindow
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.openNewWindow = function () {
    /* sdd-asis-lifecycle:begin fn_openNewWindow — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const randNum = Math.floor(Math.random() * (99999)) + 1;
    const url = location.href;
    if (url.length > 55) {
        $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(scwin.gUrl), { width: "850", height: "750", resizable: true, scrollbars: true, type: "pageFramePopup" }, {});
    } else {
        ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : (((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {})).Potential).Provider.Provider("/").window.open(scwin.gUrl, "viewer_pop2" + randNum, "left=0,top=0,width=850,height=750,resizable=yes,scrollbars=yes,location=no,status=no");
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.showLangBtn
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.showLangBtn = function () {
    /* sdd-asis-lifecycle:begin fn_ShowLangBtn — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const procs_063 = sessionStorage.getItem("gProcs_063");
    const procs_070 = sessionStorage.getItem("gProcs_070");
    const gLangTpCd = sessionStorage.getItem("gLangTpCd");
    const gSvcStatYn = sessionStorage.getItem("gSvcStatYn");
    const submitSysTp = sessionStorage.getItem("gSubmitSysTp");
    const gAttachDocYn = sessionStorage.getItem("gAttachDocYn");
    const procs_111 = sessionStorage.getItem("gProcs_111");
    const gSecuGrpEF = sessionStorage.getItem("gSecuGrpEF");
    const gDisclsEnYn = sessionStorage.getItem("gDisclsEnYn");
    const gAcptNo = sessionStorage.getItem("gAcptNo");
    const gSvrGubun = sessionStorage.getItem("gSvrGubun");
    const aKo = $c.util.getComponent('lang_ko');
    if (gSvrGubun === 'dev' || (gSvrGubun !== 'dev' && gAcptNo > '20100913000000')) {
        if (gAttachDocYn === 'N' && (procs_070 > 0 || (procs_111 > 0 && gDisclsEnYn === 'Y')) && gSvcStatYn === 'Y') {
            aKo.setStyle('visibility', "visible");
            $c.util.getComponent('btn_ko').src = "/img/btn_korean.gif";
            $c.util.getComponent('btn_en').src = "/img/btn_english_1.gif";
            if (gLangTpCd === '1') {
                aKo.setStyle('visibility', "hidden");
            }
        }
        if (submitSysTp === '1') {
            aKo.setStyle('visibility', "visible");
            $c.util.getComponent('btn_ko').src = "/img/btn_korean_1.gif";
            $c.util.getComponent('btn_en').src = "/img/btn_english.gif";
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getBodyContentByLangGb
 * @author Inswave
 * @date 2026. 09. 29
 * @param langGb
 * @returns
 * @hidden N
*/
scwin.getBodyContentByLangGb = function (langGb) {
    /* sdd-asis-lifecycle:begin fn_getBodyContentByLangGb — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let vViewLangTp = '0';
    if (langGb === 'KO') {
        vViewLangTp = '0';
        scwin.ifrCtrl.location.href = $c.str.replaceAll(scwin.gUrl, "&VIEW_LANG_TP_CD=1", "&VIEW_LANG_TP_CD=0");
        $c.util.getComponent('btn_ko').src = "/img/btn_korean.gif";
        $c.util.getComponent('btn_en').src = "/img/btn_english_1.gif";
    } else {
        vViewLangTp = '1';
        scwin.ifrCtrl.location.href = $c.str.replaceAll(scwin.gUrl, "&VIEW_LANG_TP_CD=0", "&VIEW_LANG_TP_CD=1");
        $c.util.getComponent('btn_ko').src = "/img/btn_korean_1.gif";
        $c.util.getComponent('btn_en').src = "/img/btn_english.gif";
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.viewerBtnStyleCheck
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.viewerBtnStyleCheck = function () {
    /* sdd-asis-lifecycle:begin fn_viewerBtnStyleCheck — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const url = sessionStorage.getItem("gPrintUrl");
    let formCd = "";
    let disclsDocNo = "";
    if (url.indexOf("?") != -1) {
        const queryString = url.substring(url.indexOf("?") + 1);
        const paramList = queryString.split("&");
        for (i = 0; i < paramList.length; i++) {
            let tmp = paramList[i];
            tmp = tmp.split("=");
            if (tmp[0] === "FORM_CD") {
                formCd = tmp[1];
            } else {
                if (tmp[0] === "DOC_NO") {
                    disclsDocNo = tmp[1];
                }
            }
        }
    }
    if (formCd === "99667" || formCd === "99926" || formCd === "99927") {
        scwin.fn_viewerUrl(disclsDocNo);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.addViewerOpen
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.addViewerOpen = function () {
    /* sdd-asis-lifecycle:begin addViewerOpen — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })('microsoft-edge:' + scwin.dsclViewerUrl), { id: '_self' }, {});
    /* sdd-asis-lifecycle:end */
};


// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
scwin.fn_viewerUrl = scwin.tx_fn_viewerUrl;
